/* SmartLearn Native Color Classes */
.sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-bg-primary { background-color: var(--smartlearn-primary) !important; }
.sl-hero-vid-gallery .sl-bg-primary-subtle { background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent) !important; }
.sl-hero-vid-gallery .sl-btn-primary { background-color: var(--smartlearn-btn-bg) !important; border-color: var(--smartlearn-btn-bg) !important; color: var(--smartlearn-btn-text, #ffffff) !important; }
.sl-hero-vid-gallery .sl-btn-primary:hover { background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important; filter: brightness(0.9); }
.sl-hero-vid-gallery .sl-btn-outline-primary { border-color: var(--smartlearn-primary) !important; color: var(--smartlearn-primary) !important; }
.sl-hero-vid-gallery .sl-btn-outline-primary:hover { background-color: var(--smartlearn-primary) !important; color: #fff !important; }
.sl-border-primary { border-color: var(--smartlearn-primary) !important; }
.sl-hero-vid-gallery {
    font-family: inherit;
}
.sl-hero-vid-gallery .sl-tracking-tight {
    letter-spacing: -0.04em;
}
.sl-hero-vid-gallery .sl-text-gradient {
    background: linear-gradient(135deg, var(--smartlearn-primary) 0%, var(--bs-secondary) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}
.sl-hero-vid-gallery .bg-gradient-dark-left {
    background: linear-gradient(to right, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0.4) 50%, rgba(0,0,0,0) 100%);
}
.sl-hero-vid-gallery .pointer-events-none {
    pointer-events: none;
}
.sl-hero-vid-gallery .cursor-pointer {
    cursor: pointer;
}

/* Interactivity */
.sl-hero-vid-gallery .sl-nav-btn {
    transition: transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
}
.sl-hero-vid-gallery .sl-nav-btn:hover {
    background-color: transparent;
    transform: translateX(-50%) scale(1.1);
}
.sl-hero-vid-gallery .sl-nav-btn.end-0:hover {
    transform: translateX(50%) scale(1.1);
}
.sl-hero-vid-gallery .sl-main-video-container {
    cursor: pointer;
    min-height: 380px;
    height: 380px;
    position: relative;
    width: 100%;
    background-color: #000;
}
.sl-hero-vid-gallery .sl-main-video-img {
    transition: transform 0.5s ease;
}
.sl-hero-vid-gallery .sl-main-video-container:hover .sl-main-video-img {
    transform: scale(1.05);
}
.sl-hero-vid-gallery .sl-play-main {
    transition: transform 0.2s ease;
}
.sl-hero-vid-gallery .sl-main-video-container:hover .sl-play-main {
    transform: scale(1.15) translate(-50%, -50%); /* Need to maintain translate-middle */
    transform-origin: top left; /* Complex, better to wrap it */
}
.sl-hero-vid-gallery .sl-thumb-card {
    transition: opacity 0.2s ease;
}
.sl-hero-vid-gallery .sl-thumb-card:hover {
    opacity: 0.8;
}
.sl-hero-vid-gallery .sl-feature-item {
    transition: transform 0.3s ease;
}
.sl-hero-vid-gallery .sl-feature-item:hover {
    transform: translateY(-5px);
}

/* Animations */
.sl-hero-vid-gallery .sl-animate-fade-in-up {
    opacity: 0;
    transform: translateY(30px);
    animation: slFadeInUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes slFadeInUp {
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@media (max-width: 991px) {
    .sl-hero-vid-gallery .sl-main-video-img {
        height: 250px !important;
    }
}

