(function() {
    const root = document.querySelector('.sl-hero-vid-gallery');
    if (!root) return;

    const mainContainer = root.querySelector('.sl-main-video-container');
    const playBtn = root.querySelector('.sl-play-main');
    const mainImg = root.querySelector('.sl-main-video-img');
    const urlEl = root.querySelector('.sl-item-video-url');
    const titleEl = root.querySelector('.sl-main-video-container h3');
    const descEl = root.querySelector('.sl-main-video-container p');
    const durationEl = root.querySelector('.sl-main-video-container span.bg-dark');
    const textOverlay = mainContainer ? mainContainer.querySelector('.pointer-events-none') : null;
    const gradOverlay = mainContainer ? mainContainer.querySelector('.bg-gradient-dark-left') : null;

    // Play video on click
    if (mainContainer && playBtn) {
        playBtn.addEventListener('click', (e) => {
            if (document.body.classList.contains('sl-editor-mode')) return;
            e.preventDefault();
            e.stopPropagation();

            const videoUrl = urlEl ? urlEl.innerText.trim() : 'https://www.youtube.com/embed/dQw4w9WgXcQ';
            if (!videoUrl) return;

            // Hide poster, button and overlays so video iframe is 100% visible
            if (mainImg) mainImg.style.display = 'none';
            playBtn.style.display = 'none';
            if (gradOverlay) gradOverlay.style.display = 'none';
            if (textOverlay) textOverlay.style.display = 'none';

            // Remove previous iframe if present
            const oldIframe = mainContainer.querySelector('iframe');
            if (oldIframe) oldIframe.remove();

            const iframe = document.createElement('iframe');
            iframe.src = videoUrl + (videoUrl.includes('?') ? '&' : '?') + 'autoplay=1';
            iframe.style.position = 'absolute';
            iframe.style.top = '0';
            iframe.style.left = '0';
            iframe.style.width = '100%';
            iframe.style.height = '100%';
            iframe.style.minHeight = '380px';
            iframe.style.border = 'none';
            iframe.style.zIndex = '10';
            iframe.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share');
            iframe.setAttribute('allowfullscreen', 'true');
            mainContainer.appendChild(iframe);
        });
    }

    // Thumbnail click handling
    const thumbs = root.querySelectorAll('.sl-thumb-card');
    const videoData = [
        { title: "Getting Started\nwith SmartLearn", desc: "An overview of the platform and how to get started.", duration: "02:45", url: "https://www.youtube.com/embed/dQw4w9WgXcQ" },
        { title: "Exploring Courses\n& Modules", desc: "How to find, enroll in, and navigate course content.", duration: "03:18", url: "https://www.youtube.com/embed/M7lc1UVf-VE" },
        { title: "Track Your Progress\n& Grades", desc: "Monitoring completions, quiz submissions, and stats.", duration: "02:12", url: "https://www.youtube.com/embed/LXb3EKWsInQ" },
        { title: "Certificates\n& Badges", desc: "Earning verified credentials upon course completion.", duration: "01:56", url: "https://www.youtube.com/embed/dQw4w9WgXcQ" }
    ];

    thumbs.forEach((thumb, idx) => {
        thumb.addEventListener('click', () => {
            if (document.body.classList.contains('sl-editor-mode')) return;
            const item = videoData[idx] || videoData[0];
            const thumbImg = thumb.querySelector('img');

            // Clean up running iframe and restore view
            const activeIframe = mainContainer.querySelector('iframe');
            if (activeIframe) activeIframe.remove();
            if (mainImg) {
                mainImg.style.display = '';
                if (thumbImg) mainImg.src = thumbImg.src;
            }
            if (playBtn) playBtn.style.display = '';
            if (gradOverlay) gradOverlay.style.display = '';
            if (textOverlay) textOverlay.style.display = '';

            if (titleEl) titleEl.innerText = item.title.replace('\n', ' ');
            if (descEl) descEl.innerText = item.desc;
            if (durationEl) durationEl.innerText = item.duration;
            if (urlEl) urlEl.innerText = item.url;
        });
    });
})();
